package graph

// Mapping between the domain (our business types) and the GraphQL model
// (types generated by gqlgen from schema.graphqls). Keeping this separate
// means the domain never depends on GraphQL.

import (
	"github.com/haramurti/neval-IID-staff-technicaltask/backend/graph/model"
	"github.com/haramurti/neval-IID-staff-technicaltask/backend/internal/domain"
)

func toModelFunnel(f domain.Funnel) *model.FunnelSummary {
	phases := make([]*model.PhaseCount, len(f.Phases))
	for i, p := range f.Phases {
		phases[i] = &model.PhaseCount{
			Phase:                  model.Phase(p.Phase), // same strings: "SU", "APL", ...
			Count:                  p.Count,
			ConversionFromPrevious: p.ConversionFromPrevious,
		}
	}

	return &model.FunnelSummary{
		Programme:  model.Programme(f.Programme),
		StartDate:  f.Range.Start.Format(domain.DateLayout),
		EndDate:    f.Range.End.Format(domain.DateLayout),
		Phases:     phases,
		SuToApl:    f.SuToApl,
		AplToApd:   f.AplToApd,
		ApdToRe:    f.ApdToRe,
		SuToCo:     f.SuToCo,
		DataSource: f.DataSource,
	}
}
